def check_type_list(value):
    """Verify that the value is a list or convert to a list

    A comma separated string will be split into a list. Raises a :class:`TypeError`
    if unable to convert to a list.

    :arg value: Value to validate or convert to a list

    :returns: Original value if it is already a list, single item list if a
        float, int, or string without commas, or a multi-item list if a
        comma-delimited string.
    """
    if isinstance(value, list):
        return value

    if isinstance(value, string_types):
        return value.split(",")
    elif isinstance(value, int) or isinstance(value, float):
        return [str(value)]

    raise TypeError('%s cannot be converted to a list' % type(value))


def check_type_dict(value):
    """Verify that value is a dict or convert it to a dict and return it.

    Raises :class:`TypeError` if unable to convert to a dict

    :arg value: Dict or string to convert to a dict. Accepts ``k1=v2, k2=v2``.

    :returns: value converted to a dictionary
    """
    if isinstance(value, dict):
        return value

    if isinstance(value, string_types):
        try:
            result = json.loads(value)
        except (ValueError, TypeError):
            if value.lstrip().startswith('{'):
                try:
                    result = literal_eval(value)
                except (ValueError, SyntaxError, TypeError, RecursionError) as exc:
                    raise TypeError('string is not a valid dictionary literal: %s' % exc) from exc
            else:
                fields = []
                field_buffer = []
                in_quote = None
                in_escape = False
                after_comma = False
                for c in value.strip():
                    if in_escape:
                        field_buffer.append(c)
                        in_escape = False
                    elif c == '\\':
                        in_escape = True
                    elif in_quote:
                        if c == in_quote:
                            in_quote = None
                        else:
                            field_buffer.append(c)
                    elif c in ("'", '"'):
                        in_quote = c
                    elif c == ',' or c.isspace():
                        if field_buffer:
                            fields.append(''.join(field_buffer))
                            field_buffer = []
                            after_comma = False
                        if c == ',':
                            if not fields or after_comma:
                                raise TypeError('dictionary key=value pairs contain an empty token')
                            after_comma = True
                    else:
                        field_buffer.append(c)

                if in_quote or in_escape:
                    raise TypeError('dictionary key=value pairs contain an unfinished quote or escape')
                if field_buffer:
                    fields.append(''.join(field_buffer))
                    after_comma = False
                if after_comma:
                    raise TypeError('dictionary key=value pairs end with a comma')
                if not fields:
                    raise TypeError('dictionary requested, expected JSON, a dictionary literal, or key=value pairs')
                result = {}
                for field in fields:
                    if '=' not in field:
                        raise TypeError('dictionary key=value pair %r is missing =' % field)
                    key, item = field.split('=', 1)
                    if not key or not item:
                        raise TypeError('dictionary key=value pair %r has an empty key or value' % field)
                    result[key] = item

        if not isinstance(result, dict):
            raise TypeError('dictionary requested, parsed value is %s' % type(result).__name__)
        return result

    raise TypeError('%s cannot be converted to a dict' % type(value))


def check_type_bool(value):
    """Verify that the value is a bool or convert it to a bool and return it.

    Raises :class:`TypeError` if unable to convert to a bool

    :arg value: String, int, or float to convert to bool. Valid booleans include:
         '1', 'on', 1, '0', 0, 'n', 'f', 'false', 'true', 'y', 't', 'yes', 'no', 'off'

    :returns: Boolean True or False
    """
    if isinstance(value, bool):
        return value

    if isinstance(value, string_types) or isinstance(value, (int, float)):
        return boolean(value)

    raise TypeError('%s cannot be converted to a bool' % type(value))


def check_type_int(value):
    """Verify that the value is an integer and return it or convert the value
    to an integer and return it

    Raises :class:`TypeError` if unable to convert to an int

    :arg value: String or int to convert of verify

    :return: int of given value
    """
    if isinstance(value, integer_types):
        return value

    if isinstance(value, string_types):
        try:
            return int(value)
        except ValueError:
            pass

    raise TypeError('%s cannot be converted to an int' % type(value))


